import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Composer, npm & Artisan Commands","description":"Composer scripts, npm scripts and Artisan commands available in every SaaS Laravel kit, including setup, the dev server, tests, linting and generators.","frontmatter":{"title":"Composer, npm & Artisan Commands","description":"Composer scripts, npm scripts and Artisan commands available in every SaaS Laravel kit, including setup, the dev server, tests, linting and generators.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/reference/commands.html"}],["meta",{"property":"og:title","content":"Composer, npm & Artisan Commands"}],["meta",{"property":"og:description","content":"Composer scripts, npm scripts and Artisan commands available in every SaaS Laravel kit, including setup, the dev server, tests, linting and generators."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/reference/commands.html"}],["meta",{"name":"twitter:title","content":"Composer, npm & Artisan Commands"}],["meta",{"name":"twitter:description","content":"Composer scripts, npm scripts and Artisan commands available in every SaaS Laravel kit, including setup, the dev server, tests, linting and generators."}]]},"headers":[],"relativePath":"docs/reference/commands.md","filePath":"docs/reference/commands.md","lastUpdated":1790486087000}'),r={name:"docs/reference/commands.md"};function c(n,t,s,i,p,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><p>All kits share the same Composer scripts and Artisan commands. Where a kit differs, the table says so.</p><div class="tip custom-block"><p class="custom-block-title">Most used</p><p><code>composer dev</code> to run everything locally, <code>composer lint</code> before committing, <code>php artisan tenants:migrate</code> after adding a tenant migration.</p></div><h2 id="composer-scripts" tabindex="-1">Composer scripts <a class="header-anchor" href="#composer-scripts" aria-label="Permalink to &quot;Composer scripts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it runs</th></tr></thead><tbody><tr><td><code>composer setup</code></td><td><code>composer install</code>, copy <code>.env.example</code> → <code>.env</code> (if missing), <code>php artisan key:generate</code>, <code>php artisan migrate --force</code>, <code>npm install</code>, <code>npm run build</code></td></tr><tr><td><code>composer dev</code></td><td><code>php artisan dev</code>: <code>serve</code>, <code>queue:listen --tries=1 --timeout=0</code>, <code>pail --timeout=0</code> (when <code>pcntl</code> is available), <code>npm run dev</code></td></tr><tr><td><code>composer test</code></td><td><code>config:clear</code>, <code>lint:check</code>, <code>types:check</code>, <code>php artisan test</code></td></tr><tr><td><code>composer ci:check</code></td><td><code>composer test</code> without a process timeout</td></tr><tr><td><code>composer lint</code></td><td><code>pint --parallel</code>, <code>typescript:transform</code>, <code>npm run lint:fix</code>. Vue also runs <code>wayfinder:generate --with-form</code> first.</td></tr><tr><td><code>composer lint:check</code></td><td><code>pint --parallel --test</code>, <code>npm run lint</code>. Vue also runs <code>wayfinder:generate --with-form</code> first.</td></tr><tr><td><code>composer types:check</code></td><td><code>phpstan analyse</code></td></tr></tbody></table><p>After <code>composer update</code>, the <code>post-update-cmd</code> hook publishes Laravel assets and runs <code>php artisan boost:update</code>.</p><h2 id="npm-scripts" tabindex="-1">npm scripts <a class="header-anchor" href="#npm-scripts" aria-label="Permalink to &quot;npm scripts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Vue</th><th>React</th><th>Svelte</th></tr></thead><tbody><tr><td><code>npm run dev</code></td><td><code>vite</code></td><td><code>vite</code></td><td><code>vite</code></td></tr><tr><td><code>npm run build</code></td><td><code>vite build</code></td><td><code>vite build</code></td><td><code>vite build</code></td></tr><tr><td><code>npm run build:ssr</code></td><td><code>vite build &amp;&amp; vite build --ssr</code></td><td>same</td><td>same</td></tr><tr><td><code>npm run lint</code></td><td>ESLint + Prettier check + <code>vue-tsc --noEmit</code></td><td>ESLint + Prettier check + <code>tsc --noEmit</code></td><td>ESLint + Prettier check + <code>svelte-check --tsconfig ./tsconfig.json</code></td></tr><tr><td><code>npm run lint:fix</code></td><td>ESLint <code>--fix</code> + Prettier <code>--write</code> + <code>vue-tsc --noEmit</code></td><td>ESLint <code>--fix</code> + Prettier <code>--write</code> + <code>tsc --noEmit</code></td><td>ESLint <code>--fix</code> + Prettier <code>--write</code> + <code>svelte-check --tsconfig ./tsconfig.json</code></td></tr></tbody></table><p>ESLint runs on <code>.</code> and Prettier on <code>resources/</code> in every kit.</p><h2 id="artisan" tabindex="-1">Artisan <a class="header-anchor" href="#artisan" aria-label="Permalink to &quot;Artisan&quot;">​</a></h2><h3 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>php artisan migrate</code></td><td>Central migrations</td></tr><tr><td><code>php artisan migrate --seed</code></td><td>Central migrations + <code>DatabaseSeeder</code></td></tr><tr><td><code>php artisan migrate:fresh --seed</code></td><td>Rebuild the central database (tenant DBs are not dropped)</td></tr><tr><td><code>php artisan db:seed --class=PermissionSeeder</code></td><td>Sync central permissions from <code>config/permissions</code></td></tr><tr><td><code>php artisan db:seed --class=MenuSeeder</code></td><td>Restore/add central menus</td></tr></tbody></table><h3 id="tenancy-stancl-tenancy" tabindex="-1">Tenancy (stancl/tenancy) <a class="header-anchor" href="#tenancy-stancl-tenancy" aria-label="Permalink to &quot;Tenancy (stancl/tenancy)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>php artisan tenants:list</code></td><td>List tenants and domains</td></tr><tr><td><code>php artisan tenants:migrate</code></td><td>Run <code>database/migrations/tenant</code> for all tenants</td></tr><tr><td><code>php artisan tenants:migrate --tenants=1</code></td><td>Only for tenant <code>1</code></td></tr><tr><td><code>php artisan tenants:rollback</code></td><td>Roll back tenant migrations</td></tr><tr><td><code>php artisan tenants:migrate-fresh</code></td><td>Drop and re-migrate tenant databases</td></tr><tr><td><code>php artisan tenants:seed</code></td><td>Run <code>TenantDatabaseSeeder</code> for all tenants</td></tr><tr><td><code>php artisan tenants:seed --class=&quot;Database\\Seeders\\PermissionSeeder&quot;</code></td><td>Run one seeder for all tenants</td></tr><tr><td><code>php artisan tenants:run &lt;command&gt;</code></td><td>Run any Artisan command per tenant</td></tr></tbody></table><h3 id="code-generation" tabindex="-1">Code generation <a class="header-anchor" href="#code-generation" aria-label="Permalink to &quot;Code generation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Output</th></tr></thead><tbody><tr><td><code>php artisan wayfinder:generate --with-form</code></td><td><code>resources/js/routes</code>, <code>resources/js/actions</code>, <code>resources/js/wayfinder</code></td></tr><tr><td><code>php artisan typescript:transform</code></td><td><code>resources/js/types/...</code> from Data classes and enums</td></tr><tr><td><code>php artisan erag:generate-lang</code></td><td><code>resources/js/lang/&lt;locale&gt;/*.json</code> from <code>lang/&lt;locale&gt;/*.php</code></td></tr></tbody></table><h3 id="development-and-operations" tabindex="-1">Development and operations <a class="header-anchor" href="#development-and-operations" aria-label="Permalink to &quot;Development and operations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>php artisan dev</code></td><td>Start the dev processes (same as <code>composer dev</code>)</td></tr><tr><td><code>php artisan queue:listen --tries=1</code></td><td>Development queue worker (reloads code)</td></tr><tr><td><code>php artisan queue:work</code></td><td>Production queue worker</td></tr><tr><td><code>php artisan queue:failed</code> / <code>queue:retry all</code></td><td>Inspect and retry failed jobs</td></tr><tr><td><code>php artisan pail</code></td><td>Tail logs</td></tr><tr><td><code>php artisan route:list --except-vendor</code></td><td>List application routes</td></tr><tr><td><code>php artisan test --compact</code></td><td>Run Pest</td></tr><tr><td><code>php artisan make:test --pest Name</code></td><td>New feature test</td></tr><tr><td><code>php artisan boost:update</code></td><td>Refresh Laravel Boost AI guidelines and skills</td></tr><tr><td><code>vendor/bin/pint --dirty</code></td><td>Format changed PHP files</td></tr></tbody></table><h2 id="herd" tabindex="-1">Herd <a class="header-anchor" href="#herd" aria-label="Permalink to &quot;Herd&quot;">​</a></h2><p>Use the site name that matches <code>APP_DOMAIN</code> (<code>vue</code>, <code>react</code> or <code>svelte</code> by default).</p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>herd link vue</code></td><td>Serve the current folder as <code>vue.test</code> (and <code>*.vue.test</code>)</td></tr><tr><td><code>herd secure vue</code></td><td>Enable HTTPS for the site</td></tr></tbody></table>',21)])])}const u=e(r,[["render",c]]);export{h as __pageData,u as default};
